package com.astra.tvhome;
import android.annotation.SuppressLint;import android.content.Context;import android.graphics.*;import android.hardware.camera2.*;import android.hardware.camera2.params.StreamConfigurationMap;import android.media.*;import android.os.*;import android.util.*;import android.view.*;import com.google.mediapipe.framework.image.*;import com.google.mediapipe.tasks.core.BaseOptions;import com.google.mediapipe.tasks.core.Delegate;import com.google.mediapipe.tasks.vision.core.RunningMode;import com.google.mediapipe.tasks.vision.handlandmarker.*;import java.nio.ByteBuffer;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
/** Negotiates Camera2 YUV or legacy NV21 on vendor TVs. All inference stays on-device. */
@SuppressWarnings("deprecation") final class NativeHands {
    interface Listener{void status(String s);void result(float[][][] points,float[][][] world);}
    final Context context;final Listener listener;final HandlerThread thread=new HandlerThread("Astra-Camera-Inference");final Handler worker;final HandlerThread inferenceThread=new HandlerThread("Astra-Hand-Model",1);final Handler inference;final AtomicBoolean busy=new AtomicBoolean();
    volatile boolean active;volatile int generation,frames;volatile String error="",engine="";volatile float inferenceMs,latencyMs;volatile long inferenceTotal,firstResult,lastResult;volatile int dropped;volatile boolean forceCpu,forceFull;boolean gpu;String compute="CPU";int[] pixels;Bitmap inputBitmap;CameraDevice device;CameraCaptureSession session;ImageReader reader;android.hardware.Camera legacy;HandLandmarker detector;long lastFrame;int rotation;TextureView preview;Surface previewSurface;
    NativeHands(Context c,Listener l){context=c;listener=l;thread.start();worker=new Handler(thread.getLooper());inferenceThread.start();inference=new Handler(inferenceThread.getLooper());}
    void start(){if(active)return;active=true;error="";frames=dropped=0;inferenceTotal=firstResult=lastResult=0;lastFrame=0;final int token=++generation;listener.status("正在加载本地手部模型…");inference.post(()->{try{createDetector(!forceCpu);if(!valid(token))return;worker.post(()->{try{connect(token);}catch(Throwable e){fail(e,token);}});}catch(Throwable e){fail(e,token);}});}
    void createDetector(boolean preferGpu){
        if(detector!=null){detector.close();detector=null;}
        try{gpu=preferGpu;detector=HandLandmarker.createFromOptions(context,HandLandmarker.HandLandmarkerOptions.builder().setBaseOptions(BaseOptions.builder().setModelAssetPath(!forceFull&&((MainActivity)context).pref().getInt("handQuality",0)==0?"hand_landmarker_fast.task":"hand_landmarker.task").setDelegate(gpu?Delegate.GPU:Delegate.CPU).build()).setRunningMode(RunningMode.VIDEO).setNumHands(2).setMinHandDetectionConfidence(.5f).setMinHandPresenceConfidence(.45f).setMinTrackingConfidence(.35f).build());compute=gpu?"GPU":"CPU";}
        catch(RuntimeException e){if(!preferGpu)throw e;Log.w("ASTRA_CAMERA","GPU unavailable; use CPU",e);createDetector(false);}
    }
    boolean takeFrame(long now,int token){if(!valid(token)||now-lastFrame<45||!busy.compareAndSet(false,true)){dropped++;return false;}lastFrame=now;return true;}
    boolean valid(int t){return active&&generation==t;}
    @SuppressLint("MissingPermission") void connect(int token)throws Exception{
        CameraManager manager=(CameraManager)context.getSystemService(Context.CAMERA_SERVICE);String chosen=null;for(String id:manager.getCameraIdList()){if(chosen==null)chosen=id;Integer facing=manager.getCameraCharacteristics(id).get(CameraCharacteristics.LENS_FACING);if(facing!=null&&facing==CameraCharacteristics.LENS_FACING_FRONT){chosen=id;break;}}if(chosen==null)throw new Exception("系统未开放摄像头");CameraCharacteristics c=manager.getCameraCharacteristics(chosen);Integer angle=c.get(CameraCharacteristics.SENSOR_ORIENTATION);rotation=angle==null?0:angle;StreamConfigurationMap map=c.get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP);Size[] sizes=map==null?null:map.getOutputSizes(ImageFormat.YUV_420_888);
        listener.status("正在连接摄像头…");if(sizes==null||sizes.length==0){engine="NV21 兼容模式";waitLegacy(token,0);return;}engine="Camera2 YUV";Size size=sizes[0];for(Size option:sizes)if(Math.abs(option.getWidth()-640)+Math.abs(option.getHeight()-480)<Math.abs(size.getWidth()-640)+Math.abs(size.getHeight()-480))size=option;reader=ImageReader.newInstance(size.getWidth(),size.getHeight(),ImageFormat.YUV_420_888,2);reader.setOnImageAvailableListener(r->frame(r,token),worker);
        manager.openCamera(chosen,new CameraDevice.StateCallback(){public void onOpened(CameraDevice cam){if(!valid(token)){cam.close();return;}device=cam;try{List<Surface> targets=new ArrayList<>();targets.add(reader.getSurface());if(preview!=null&&preview.isAvailable()){SurfaceTexture t=preview.getSurfaceTexture();t.setDefaultBufferSize(reader.getWidth(),reader.getHeight());previewSurface=new Surface(t);targets.add(previewSurface);}cam.createCaptureSession(targets,new CameraCaptureSession.StateCallback(){public void onConfigured(CameraCaptureSession s){if(!valid(token)){s.close();return;}session=s;try{CaptureRequest.Builder request=cam.createCaptureRequest(CameraDevice.TEMPLATE_PREVIEW);for(Surface target:targets)request.addTarget(target);s.setRepeatingRequest(request.build(),null,worker);listener.status("摄像头已连接 · 等待识别");}catch(Exception e){fail(e,token);}}public void onConfigureFailed(CameraCaptureSession s){fail(new Exception("摄像头视频配置失败"),token);}},worker);}catch(Exception e){fail(e,token);}}public void onDisconnected(CameraDevice cam){cam.close();fail(new Exception("摄像头已断开"),token);}public void onError(CameraDevice cam,int code){cam.close();fail(new Exception("摄像头错误 "+code),token);}},worker);
    }
    void waitLegacy(int token,int retries){if(!valid(token))return;if(preview==null||!preview.isAvailable()){if(retries>40){fail(new Exception("摄像头预览未就绪"),token);return;}worker.postDelayed(()->waitLegacy(token,retries+1),75);return;}try{int id=0;for(int i=0;i<android.hardware.Camera.getNumberOfCameras();i++){android.hardware.Camera.CameraInfo info=new android.hardware.Camera.CameraInfo();android.hardware.Camera.getCameraInfo(i,info);if(info.facing==android.hardware.Camera.CameraInfo.CAMERA_FACING_FRONT){id=i;rotation=info.orientation;break;}}legacy=android.hardware.Camera.open(id);android.hardware.Camera.Parameters p=legacy.getParameters();List<Integer> formats=p.getSupportedPreviewFormats();if(formats==null||!formats.contains(ImageFormat.NV21))throw new Exception("电视没有开放兼容视频格式");android.hardware.Camera.Size best=p.getSupportedPreviewSizes().get(0);for(android.hardware.Camera.Size size:p.getSupportedPreviewSizes())if(Math.abs(size.width-640)+Math.abs(size.height-480)<Math.abs(best.width-640)+Math.abs(best.height-480))best=size;p.setPreviewFormat(ImageFormat.NV21);p.setPreviewSize(best.width,best.height);legacy.setParameters(p);int w=best.width,h=best.height;preview.getSurfaceTexture().setDefaultBufferSize(w,h);legacy.setPreviewTexture(preview.getSurfaceTexture());legacy.setDisplayOrientation(rotation);for(int i=0;i<3;i++)legacy.addCallbackBuffer(new byte[w*h*3/2]);legacy.setPreviewCallbackWithBuffer((bytes,camera)->{long now=SystemClock.uptimeMillis();if(!takeFrame(now,token)){if(valid(token)&&legacy==camera)camera.addCallbackBuffer(bytes);return;}inference.post(()->{try{if(valid(token))infer(nv21(bytes,w,h),now,token);}catch(Throwable e){inferenceFailure(e,token);}finally{busy.set(false);worker.post(()->{if(valid(token)&&legacy==camera)camera.addCallbackBuffer(bytes);});}});});legacy.setErrorCallback((code,camera)->fail(new Exception("兼容摄像头错误 "+code),token));legacy.startPreview();listener.status("摄像头已连接 · 等待识别");}catch(Throwable e){fail(e,token);}}
    void frame(ImageReader source,int token){Image image=null;try{image=source.acquireLatestImage();if(image==null)return;long now=SystemClock.uptimeMillis();if(!takeFrame(now,token)){image.close();return;}Image captured=image;image=null;inference.post(()->{try{if(valid(token))infer(convert(captured),now,token);}catch(Throwable e){inferenceFailure(e,token);}finally{captured.close();busy.set(false);}});}catch(Throwable e){fail(e,token);}finally{if(image!=null)image.close();}}
    void inferenceFailure(Throwable e,int token){if(!valid(token))return;if(gpu){Log.w("ASTRA_CAMERA","GPU execution failed; switch to CPU",e);try{createDetector(false);return;}catch(Throwable fallback){e=fallback;}}fail(e,token);}
    void infer(Bitmap bitmap,long now,int token){Bitmap rotated=bitmap;MPImage input=null;try{if(rotation!=0){Matrix m=new Matrix();m.postRotate(rotation);rotated=Bitmap.createBitmap(bitmap,0,0,bitmap.getWidth(),bitmap.getHeight(),m,true);}input=new BitmapImageBuilder(rotated).build();long start=SystemClock.uptimeMillis();HandLandmarkerResult result=detector.detectForVideo(input,now);inferenceMs=SystemClock.uptimeMillis()-start;latencyMs=SystemClock.uptimeMillis()-now;if(!valid(token))return;frames++;inferenceTotal+=(long)inferenceMs;lastResult=SystemClock.uptimeMillis();if(firstResult==0)firstResult=lastResult;int n=result.landmarks().size();float[][][] points=new float[n][21][3],world=new float[n][21][3];for(int h=0;h<n;h++)for(int i=0;i<21;i++){var p=result.landmarks().get(h).get(i);points[h][i]=new float[]{p.x(),p.y(),p.z()};var q=result.worldLandmarks().get(h).get(i);world[h][i]=new float[]{q.x(),q.y(),q.z()};}listener.result(points,world);}finally{if(input!=null)input.close();if(rotated!=bitmap)rotated.recycle();}}
    int rgb(int y,int u,int v){y=Math.max(0,y-16);u-=128;v-=128;int r=(298*y+409*v+128)>>8,g=(298*y-100*u-208*v+128)>>8,b=(298*y+516*u+128)>>8;return 0xff000000|(r<0?0:r>255?255:r)<<16|(g<0?0:g>255?255:g)<<8|(b<0?0:b>255?255:b);}
    void ensureInput(int w,int h){if(inputBitmap!=null&&!inputBitmap.isRecycled()&&inputBitmap.getWidth()==w&&inputBitmap.getHeight()==h)return;if(inputBitmap!=null&&!inputBitmap.isRecycled())inputBitmap.recycle();if(pixels==null||pixels.length!=w*h)pixels=new int[w*h];inputBitmap=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);}
    Bitmap nv21(byte[] bytes,int iw,int ih){int step=2,w=iw/step,h=ih/step;ensureInput(w,h);for(int y=0;y<h;y++)for(int x=0;x<w;x++){int yy=y*step,xx=x*step,uv=iw*ih+(yy/2)*iw+(xx&~1);pixels[y*w+x]=rgb(bytes[yy*iw+xx]&255,bytes[uv+1]&255,bytes[uv]&255);}inputBitmap.setPixels(pixels,0,w,0,0,w,h);return inputBitmap;}
    Bitmap convert(Image image){int iw=image.getWidth(),ih=image.getHeight(),step=2,w=iw/step,h=ih/step;ensureInput(w,h);Image.Plane[] p=image.getPlanes();ByteBuffer y=p[0].getBuffer(),u=p[1].getBuffer(),v=p[2].getBuffer();for(int row=0;row<h;row++)for(int col=0;col<w;col++){int xx=col*step,yy=row*step;pixels[row*w+col]=rgb(y.get(yy*p[0].getRowStride()+xx*p[0].getPixelStride())&255,u.get((yy/2)*p[1].getRowStride()+(xx/2)*p[1].getPixelStride())&255,v.get((yy/2)*p[2].getRowStride()+(xx/2)*p[2].getPixelStride())&255);}inputBitmap.setPixels(pixels,0,w,0,0,w,h);return inputBitmap;}
    void fail(Throwable e,int token){if(!valid(token))return;error=e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();Log.e("ASTRA_CAMERA",error,e);stop();listener.status("摄像头未连接："+error);}
    void stop(){active=false;generation++;worker.post(()->{if(legacy!=null){legacy.setPreviewCallbackWithBuffer(null);legacy.stopPreview();legacy.release();legacy=null;}if(session!=null){session.close();session=null;}if(device!=null){device.close();device=null;}if(reader!=null){reader.close();reader=null;}if(previewSurface!=null){previewSurface.release();previewSurface=null;}});inference.post(()->{if(detector!=null){detector.close();detector=null;}if(inputBitmap!=null){inputBitmap.recycle();inputBitmap=null;pixels=null;}busy.set(false);});}
    void close(){stop();worker.post(thread::quitSafely);inference.post(inferenceThread::quitSafely);}
}
